using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using System;using System.IO;using System.Linq;using System.Collections.Generic;
public static class CoastPackage{
const string D="Assets/Lighthouse_Authored/Prefabs/";
static void Group(string name,Func<MeshRenderer,bool> select){var parts=UnityEngine.Object.FindObjectsByType<MeshRenderer>().Where(select).ToArray();if(parts.Length==0)return;var b=parts[0].bounds;foreach(var r in parts)b.Encapsulate(r.bounds);var pivot=new Vector3(b.center.x,b.min.y,b.center.z);var group=new GameObject(name);group.transform.position=pivot;foreach(var r in parts)r.transform.SetParent(group.transform,true);group.transform.position=Vector3.zero;PrefabUtility.SaveAsPrefabAsset(group,D+name+".prefab");group.transform.position=pivot;}
public static void Save(){
Group("Lighthouse_complete",r=>r.name.StartsWith("Lighthouse")||r.name.StartsWith("Lantern")||r.name.StartsWith("Balcony")||r.name.StartsWith("Door")||r.name.StartsWith("Blue oak")||r.name.StartsWith("Window"));
Group("Keeper_cottage",r=>r.name.StartsWith("Keeper cottage")||r.name.StartsWith("Roof tile")||r.name.StartsWith("Cottage chimney")||r.name.StartsWith("Cottage blue"));
Group("Coastal_palm_left",r=>r.name.StartsWith("Coastal palm left"));Group("Coastal_palm_right",r=>r.name.StartsWith("Coastal palm right"));
foreach(var r in UnityEngine.Object.FindObjectsByType<MeshRenderer>().Where(r=>r.name.StartsWith("Shore rock")).ToArray()){var pick=r;Group("Shore_"+r.name.Substring(r.name.IndexOf('•')+1).Trim().Replace(' ','_'),q=>q==pick);}
var player=GameObject.Find("Explorer");var info=new List<string>();foreach(var r in player.GetComponentsInChildren<Renderer>())info.Add(r.name+" | "+string.Join(",",r.sharedMaterials.Select(m=>m?m.name+":"+m.shader.name:"MISSING")));File.WriteAllLines("ArtSource/Lighthouse_Authored/actor-renderers.txt",info);
EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();var deps=AssetDatabase.GetDependencies(CoastAuthored.Scene,true);File.WriteAllLines("Docs/Lighthouse_Authored/SCENE_DEPENDENCIES.txt",deps);var errors=new List<string>();int meshes=0,triangles=0,colliders=0;foreach(var f in UnityEngine.Object.FindObjectsByType<MeshFilter>()){if(!f.sharedMesh){errors.Add("Missing mesh: "+f.name);continue;}meshes++;triangles+=f.sharedMesh.triangles.Length/3;}foreach(var r in UnityEngine.Object.FindObjectsByType<Renderer>())foreach(var m in r.sharedMaterials){if(!m)errors.Add("Missing material: "+r.name);else if(!m.shader||!m.shader.isSupported||ShaderUtil.ShaderHasError(m.shader))errors.Add("Unsupported or invalid shader: "+r.name);}colliders=UnityEngine.Object.FindObjectsByType<Collider>().Length;File.WriteAllText("Docs/Lighthouse_Authored/SCENE_VALIDATION.txt",(errors.Count==0?"PASS":"FAIL")+"\nMesh objects: "+meshes+"\nStatic mesh triangles: "+triangles+"\nColliders: "+colliders+"\nScene dependencies: "+deps.Length+"\n"+string.Join("\n",errors));Debug.Log("COAST_PACKAGE_SAVED errors="+errors.Count);if(errors.Count>0)throw new Exception(string.Join(";",errors));}
public static void Run(){CoastAuthored.Build();CoastPolish.Apply();Save();CoastShots.Save();CoastPlayCheck.Begin();}
}
